import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { API, PACKAGE, jsonRequest, waitFor } from './support.mjs';
import { takePhoto, verifyPhoto, verifyCachedPhoto } from './photo-flow.mjs';

/** Control only the Compose project generated by this invocation's owner. */
function apiService(action) {
  const project = process.env.E2E_COMPOSE_PROJECT;
  assert.match(project ?? '', /^catchlogr-e2e-[a-f0-9]{12}$/);
  assert(['stop', 'start'].includes(action));
  execFileSync('docker', ['compose', '--project-name', project,
    '--file', 'deploy/e2e/compose.yml', action, 'api'], { stdio: 'ignore', timeout: 60000 });
}

async function createTrip(android, name) {
  console.log('  UI: open trip form');
  await android.click('AddTripButton');
  await android.fill('TripNameEntry', name);
  await android.fill('TripLocationEntry', 'E2E lake');
  await android.scrollTo('SaveTripButton');
  await android.click('SaveTripButton');
  console.log('  UI: saved trip, opening details');
  await android.waitText(name);
  await android.tapText(name);
  await android.waitText('AddCatchButton');
}

async function createCatch(android, species, photo = false) {
  console.log('  UI: open catch form');
  await android.click('AddCatchButton');
  await android.fill('CatchSpeciesEntry', species);
  if (photo) await takePhoto(android);
  await android.scrollTo('CatchLengthEntry');
  await android.fill('CatchLengthEntry', '42');
  await android.fill('CatchWeightEntry', '900');
  await android.scrollTo('SaveCatchButton');
  await android.click('SaveCatchButton');
  console.log('  UI: saved catch, returning to trip list');
  await android.waitText(species);
  await android.back(); // Trip list appearance runs the real sync orchestrator.
}

async function records(headers) {
  const trips = await jsonRequest(`${API}/api/fishing-trips`, { headers });
  const catches = await jsonRequest(`${API}/api/catches`, { headers });
  return { trips, catches };
}

async function verifyUpload(headers, name, species, photo = false) {
  return waitFor('trip and catch upload', async () => {
    const { trips, catches } = await records(headers);
    const trip = trips.find(item => item.name === name);
    const caught = catches.find(item => item.species === species);
    if (!trip || !caught) return false;
    if (photo && !caught.photoUrl) return false;
    assert.equal(caught.fishingTripId, trip.id, 'Catch must have its uploaded parent GUID');
    assert.equal(trip.locationName, 'E2E lake');
    assert.equal(caught.length, 42);
    assert.equal(caught.weight, 900);
    assert.equal(trips.filter(item => item.name === name).length, 1);
    assert.equal(catches.filter(item => item.species === species).length, 1);
    return { trip, caught };
  });
}

async function recoverOffline(android, headers) {
  apiService('stop');
  try {
    await createTrip(android, 'Offline E2E trip');
    await createCatch(android, 'Offline E2E perch');
    await android.waitText('Offline E2E trip');
    // Relaunch while the API is still stopped: this proves SQLite persistence.
    await android.command('POST', `${android.prefix}/execute/sync`, {
      script: 'mobile: terminateApp', args: [{ appId: PACKAGE }],
    });
    await android.command('POST', `${android.prefix}/execute/sync`, {
      script: 'mobile: activateApp', args: [{ appId: PACKAGE }],
    });
    await android.waitText('Offline E2E trip');
  } finally {
    apiService('start');
  }
  await waitFor('restored API', async () => {
    try { return (await fetch(`${API}/health`, { signal: AbortSignal.timeout(2000) })).ok; }
    catch { return false; }
  });
  // Navigate away/back to trigger the documented list appearance sync.
  await android.tapText('Offline E2E trip');
  await android.waitText('Offline E2E perch');
  await android.back();
  await verifyUpload(headers, 'Offline E2E trip', 'Offline E2E perch');
}

async function freshDownload(android, email, password) {
  await android.stop();
  execFileSync(`${process.env.ANDROID_HOME}/platform-tools/adb`,
    ['-s', process.env.E2E_DEVICE, 'shell', 'pm', 'clear', PACKAGE], { stdio: 'ignore', timeout: 30000 });
  await android.start();
  await android.fill('LoginEmailEntry', email);
  await android.fill('LoginPasswordEntry', password);
  await android.click('LoginButton');
  await android.waitText('Online E2E trip');
  await android.waitText('Offline E2E trip');
  await android.tapText('Online E2E trip');
  await android.waitText('Online E2E pike');
  await android.back();
  await android.tapText('Offline E2E trip');
  await android.waitText('Offline E2E perch');
  await android.back();
}

/** Exercise real UI, SQLite, sync, authenticated API and disposable PostgreSQL. */
export async function syncFlow(android, tokens, email, password) {
  const headers = { Authorization: `Bearer ${tokens.accessToken}` };
  console.log('STEP: online trip and catch upload');
  await createTrip(android, 'Online E2E trip');
  await createCatch(android, 'Online E2E pike', true);
  const { caught } = await verifyUpload(headers, 'Online E2E trip', 'Online E2E pike', true);
  const photo = await verifyPhoto(caught, headers);
  console.log('PASS: online trip and catch upload');
  console.log('STEP: API outage, local persistence and recovery');
  await recoverOffline(android, headers);
  console.log('PASS: API outage, local persistence and recovery');
  console.log('STEP: fresh app download and repeat sync without duplicates');
  await freshDownload(android, email, password);
  await verifyCachedPhoto(photo.hash);
  await android.refresh();
  await verifyUpload(headers, 'Online E2E trip', 'Online E2E pike');
  await verifyUpload(headers, 'Offline E2E trip', 'Offline E2E perch');
  const result = await records(headers);
  assert.equal(result.trips.length, 2);
  assert.equal(result.catches.length, 2);
  console.log('PASS: fresh app download and repeat sync without duplicates');
}
